INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'obligation'), (SELECT id FROM languages WHERE code = 'en'), 'Having to: “…ayla pahije” and “…ava lagel”', '“Mala uthayla pahije” = I should / have to get up. “Tumhala form bharava lagel” = you will have to fill in the form (the verb follows the thing to be done). “Mala … karaycha aahe” = I want / intend to do …');
INSERT INTO grammar_examples(grammar_topic_id, item_id, language_id, sort_order) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'obligation'), (SELECT id FROM vocabulary_items WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND text = 'मला उद्या लवकर उठायला पाहिजे.'), (SELECT id FROM languages WHERE code = 'mr'), 1);
