INSERT INTO lesson_grammar(lesson_id, grammar_topic_id, language_id) VALUES ((SELECT id FROM lessons WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'obligations'), (SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'obligation'), (SELECT id FROM languages WHERE code = 'mr'));
INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'mr'), 'B1', 'conditions', 2);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'conditions'), (SELECT id FROM languages WHERE code = 'en'), 'If … then: “jar … tar”', '“Tar” (then) follows the condition and “jar” (if) is often dropped: “paaus padla tar …” = if it rains …. For what did not happen, add “asta”: “mahit asta tar mi saangitla asta” = if I''d known, I''d have told you.');
INSERT INTO grammar_examples(grammar_topic_id, item_id, language_id, sort_order) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'conditions'), (SELECT id FROM vocabulary_items WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND text = 'जर पाऊस पडला, तर आपण टॅक्सी घेऊ.'), (SELECT id FROM languages WHERE code = 'mr'), 1);
