INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'mr'), 'B1', 'ability', 3);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'ability'), (SELECT id FROM languages WHERE code = 'en'), 'Can and can''t: “yeta” and “shak-”', 'A skill “comes” to you: “mala Marathi bolta yeta” (I can speak Marathi), “yet nahi” (I can''t). Being able to on a given occasion uses “shak-”: “mi yeu shaknar nahi” (I won''t be able to come), “madat karu shakal ka?” (could you help?).');
INSERT INTO grammar_examples(grammar_topic_id, item_id, language_id, sort_order) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'ability'), (SELECT id FROM vocabulary_items WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND text = 'मला थोडं मराठी बोलता येतं.'), (SELECT id FROM languages WHERE code = 'mr'), 1);
