INSERT INTO grammar_examples(grammar_topic_id, item_id, language_id, sort_order) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'ability'), (SELECT id FROM vocabulary_items WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND text = 'मी उद्या येऊ शकणार नाही.'), (SELECT id FROM languages WHERE code = 'mr'), 3);
