INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'mr'), 'B1', 'opinion', 4);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'opinion'), (SELECT id FROM languages WHERE code = 'en'), 'Opinions: “mala vaatta ki …”', '“Mala vaatta ki …” (it seems to me that …) introduces an opinion; “maajha mat …” is “my opinion …”. “Mhanun” means “so, that''s why”: “mhanunach mi trainne yeto” = that''s exactly why I take the train.');
INSERT INTO grammar_examples(grammar_topic_id, item_id, language_id, sort_order) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'opinion'), (SELECT id FROM vocabulary_items WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND text = 'मला वाटतं की हा चांगला पर्याय आहे.'), (SELECT id FROM languages WHERE code = 'mr'), 1);
