INSERT INTO grammar_examples(grammar_topic_id, item_id, language_id, sort_order) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'opinion'), (SELECT id FROM vocabulary_items WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND text = 'म्हणूनच मी ट्रेनने येतो.'), (SELECT id FROM languages WHERE code = 'mr'), 3);
INSERT INTO lesson_grammar(lesson_id, grammar_topic_id, language_id) VALUES ((SELECT id FROM lessons WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'opinions'), (SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'opinion'), (SELECT id FROM languages WHERE code = 'mr'));
INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'mr'), 'B1', 'linking', 5);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'linking'), (SELECT id FROM languages WHERE code = 'en'), 'Who, when and what was said', 'Marathi pairs its linking words: “jo … to” (the one who … he), “jevha … tevha” (when … then; the “jevha” is often left out). To report what someone said, add “ki”: “to mhanala ki bus ushira yeil” = he said (that) the bus would be late.');
INSERT INTO grammar_examples(grammar_topic_id, item_id, language_id, sort_order) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'linking'), (SELECT id FROM vocabulary_items WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND text = 'जो माणूस आत्ताच गेला, तो माझा शेजारी आहे.'), (SELECT id FROM languages WHERE code = 'mr'), 1);
